package com.sliverzfx.gothicquest

object NewBalanceChapter2Part4 {
    val quests = listOf(
        Quest("CH2-130",2,130,"Tengron's Ring",category="Valley of Mines",giver = "Tengron",location="Valley of Mines",prerequisites="Start Miners and Ore and reach Fajeth's mining camp in the Valley of Mines.",summary="Carry the paladin Tengron's ring from Fajeth's mining camp to Udar in the castle.",walkthroughSteps=listOf("Find Tengron, the paladin stationed at the entrance to Fajeth's mining camp.","Accept his request to deliver a ring to fellow paladin Udar.","Travel to Garond's castle and find Udar on guard duty.","Hand over Tengron's ring to Udar to complete the errand."),reward="500 XP and +2 Innos karma.",warnings="Complete the related faction and chapter prerequisites before this objective. Source: https://rpgrussia.com/threads/kolco-tengrona.67091/",searchTags=listOf("tengron's ring","valley of mines","local quest giver in valley of mines")),
        Quest("CH2-131",2,131,"Reinforcements for Marcos",category="Valley of Mines",giver="Marcos",location="Valley of Mines",prerequisites="Chapter 2; Find Marcos at his Valley of Mines position.",summary="Ask Garond to send reinforcements to Marcos.",walkthroughSteps=listOf("Find Marcos at his Valley of Mines position.","Ask how you can help; he requests additional troops.","Go to Garond in the castle and ask for support for Marcos.","Return to Marcos when the support request has been dealt with."),reward="Garond arranges support for Marcos after you report his situation; exact XP not verified.",warnings="Speak to Garond about Marcos's need for help, then revisit Marcos for completion.",searchTags=listOf("reinforcements for marcos","valley of mines","local quest giver in valley of mines","marcos")),
        Quest("CH2-132",2,132,"Hunting Glorks",category="Valley of Mines",giver="Fajeth",location="Valley of Mines",prerequisites="Start Miners and Ore by Garond, then speak with Fajeth at his ore miners' camp.",summary="Kill eight specific snappers (glorks) threatening Fajeth's mining camp, then report to him.",walkthroughSteps=listOf("Travel to Fajeth's mining camp in the Valley of Mines while following Garond's Miners and Ore assignment.","Speak to Fajeth; he asks you to kill the snappers (glorks) surrounding his camp.","Kill three snappers beside the lake; one spawns only after Fajeth gives the quest. Nearby dragon snappers do not count.","Kill two more along the road toward Xardas's old tower; again, dragon snappers accompanying them are not part of the count.","Climb the ledge above the mining camp and kill three more snappers; two appear only once the hunt has started.","Report the eight kills to Fajeth to complete his quest.","Before leaving, speak to Bilgot about the pack leader to unlock the associated special snapper and his optional escape quest. The leader is guarded by three dragon snappers but does not count toward the required eight."),reward="1,000 XP for Fajeth's snapper hunt; an optional 800 XP for the special pack leader, according to the April 2026 New Balance guide.",warnings="This is a separate quest from Kervo's Snappers (CH2-124). The eight required creatures are: 3 by the lake, 2 by the road to Xardas's tower, 3 on the ledge above camp. Dragon snappers, the leader and its escorts do not count. Source: https://rpgrussia.com/threads/oxota-na-glorxov.67088/",searchTags=listOf("hunting glorks","valley of mines","local quest giver in valley of mines")),
