        Quest("CH2-134",2,134,"Forest Camp",category="Valley of Mines",giver="Isidro",location="Valley of Mines",prerequisites="Chapter 2; Meet Isidro on the road toward the forest camp behind the orc palisade.",summary="Escort Isidro through the boar-infested route to the secluded forest camp in the Valley of Mines.",walkthroughSteps=listOf("Meet Isidro on the road toward the forest camp behind the orc palisade.","Speak to Isidro about joining the camp and his request for a safe path.","Clear the boars near the bridge before beginning the escort.","Follow the forest path with Isidro, reaching the fire where Drax, Ratford and Angar are staying.","Cross the bridge and complete Isidro's arrival conversation."),reward="Escort Isidro to the Valley of Mines forest camp, opening access to its quests and services; exact XP not verified.",warnings="Verify the camp-approach route in your New Balance build. Source: https://rpgrussia.com/threads/lesnoj-lager.66936/",searchTags=listOf("forest camp","valley of mines","local quest giver in valley of mines")),
