        Quest("CH2-136",2,136,"Raven's Ring",category="Valley of Mines",giver="Drax",location="Valley of Mines",prerequisites="Chapter 2; Speak to Drax at the camp beyond the orc palisade.",summary="Bring Raven's ring to Drax at the forest camp behind the palisade.",walkthroughSteps=listOf("Speak to Drax at the camp beyond the orc palisade.","Fight Raven in the Temple of Adanos and obtain his ring.","Return to Drax and deliver the ring."),reward="Give Raven's ring to Drax after defeating Raven; exact XP or gold not verified.",warnings="Keep Raven's ring after his defeat if you plan to deliver it to Drax.",searchTags=listOf("raven's ring","valley of mines","local quest giver in valley of mines","drax")),
        Quest("CH2-137",2,137,"Greetings from Ratford",category="Valley of Mines",giver="Ratford",location="Valley of Mines",prerequisites="Return Raven's ring to Drax.",summary="Carry Ratford's greeting to Fisk and return with the package.",walkthroughSteps=listOf("After handing Raven's ring to Drax, speak to Ratford.","Visit Fisk in the Jharkendar bandit camp and pass on Ratford's greeting.","Collect Fisk's package and bring it back to Ratford."),reward="Deliver Ratford's greetings to Fisk, then return Fisk's package to Ratford; exact XP not verified.",warnings="Ratford rewards the delivery with a King's Sorrel.",searchTags=listOf("greetings from ratford","valley of mines","local quest giver in valley of mines","ratford")),
        Quest("CH2-138",2,138,"Uninvited Guest",category="Valley of Mines",giver="Netbek",location="Valley of Mines",prerequisites="Chapter 2; Talk to Netbek in his forest camp in the Valley of Mines.",summary="Kill the large troll threatening Netbek's woodland camp.",walkthroughSteps=listOf("Talk to Netbek in his forest camp in the Valley of Mines.","Find the giant troll between the Tower of Mists and the cliff above the former Brotherhood camp.","Kill the troll and report back to Netbek."),reward="Remove the giant troll threatening Netbek's camp; exact XP/gold not verified.",warnings="The giant troll is between the Tower of Mists and the cliff above the old Brotherhood camp.",searchTags=listOf("uninvited guest","valley of mines","local quest giver in valley of mines","netbek")),
        Quest("CH2-139",2,139,"Heart of the Harpy Queen",category="Valley of Mines",giver="Gestath",location="Valley of Mines",prerequisites="Chapter 2; Speak with hunter Gestath about the Harpy Queen.",summary="Defeat the Harpy Queen and bring her heart to Gestath.",walkthroughSteps=listOf("Speak with hunter Gestath about the Harpy Queen.","Find her in the Stone Fortress on the route toward the stone dragon.","Defeat the queen, loot her heart, and return it to Gestath."),reward="Return the Harpy Queen's heart to Gestath; complete his rare-monster request before recruiting him elsewhere.",warnings="Accept Heart of the Harpy Queen before recruiting Gestath to the Hunters' Camp, as recruiting him can remove the quest.",searchTags=listOf("heart of the harpy queen","valley of mines","local quest giver in valley of mines","gestath")),
        Quest("CH2-140",2,140,"Ur-Shak",category="Valley of Mines",giver = "Ur-Shak",location="Valley of Mines",prerequisites="Chapter 2; Find Ur-Shak on the hill near Xardas's old tower and ask about his position among the orcs.",summary="Help friendly orc shaman Ur-Shak regain his standing by asking Ur-Thrall to speak for him.",walkthroughSteps=listOf("Find Ur-Shak on the hill near Xardas's old tower and ask about his position among the orcs.","Ur-Shak asks you to speak favorably of him to orc chieftain Ur-Thrall if an opportunity arises.","Complete Ur-Thrall's Revenge and defeat Azgalor in the Valley of Shadows.","Keep Ur-Grom alive and in corporeal form; tell Ur-Thrall that his brother Ur-Grom survived.","When Ur-Thrall offers to grant a request in thanks, ask him to help Ur-Shak.","Return to Ur-Shak to tell him the good news and close the quest."),reward="Help Ur-Shak regain status via Ur-Thrall's promised favor; unlocks further friendly orc interactions.",warnings="Do not kill Hosh-Pak or turn Ur-Shak hostile if pursuing his reconciliation route. Ur-Thrall's favor is needed.",searchTags=listOf("ur-shak","valley of mines","local quest giver in valley of mines")),
        Quest("CH2-141",2,141,"Orc Drakkar",category="Valley of Mines",giver="Albert",location="Valley of Mines",prerequisites="Complete Albert's initial request for orders from Garond.",summary="Sabotage the orc warship's mechanism at Albert's request.",walkthroughSteps=listOf("Speak to Albert at the small paladin camp below Netbek's forest camp.","Reach the orc drakkar nearby and enter its hold.","Set the ship's internal mechanism on fire using a torch.","Escape and report the sabotage to Albert."),reward="Destroy the orc Drakkar's mechanism and report to paladin Albert; exact XP not verified.",warnings="Ulu-Mulu will not protect you aboard the ship. Orc armor or an invisibility potion may help.",searchTags=listOf("orc drakkar","valley of mines","local quest giver in valley of mines","albert")),
        Quest("CH2-142",2,142,"Orc War Plans",category="Valley of Mines",giver="Albert",location="Valley of Mines",prerequisites="Progress Albert's orc drakkar quest and clear the orcs on the ship.",summary="Recover and decipher the orc war plans, then stop their construction project.",walkthroughSteps=listOf("Kill the orcs on the drakkar, including their leader, and take the letter from the chief.","Show the orc-language note to Albert.","Ask Ur-Shak to translate it, or learn to read the orc language from the note in Xardas's old tower.","The plans reveal a new battering ram aimed at the castle.","Find the orcs near the breach in the palisade, defeat them and return to Albert."),reward="Find the orc war plans, prevent construction of the battering ram and report to Albert; exact XP not verified.",warnings="Albert offers two paladins as support, but you need not take them along.",searchTags=listOf("orc war plans","valley of mines","local quest giver in valley of mines","albert")),
        Quest("CH2-143",2,143,"Bring Meat",category="Valley of Mines - Castle",giver="Engor",location="Valley of Mines - Castle",prerequisites="Chapter 2; Speak with Parlaf about the food shortage inside the castle.",summary="Provide raw meat to the hungry soldiers in Garond's castle.",walkthroughSteps=listOf("Speak with Parlaf about the food shortage inside the castle.","Offer Engor help with supplies.","Bring Engor 24 pieces of raw meat."),reward="Deliver 24 raw meat to Engor in Garond's castle; exact XP or payment not verified.",warnings="Engor asks for 24 pieces of raw meat, not cooked meat.",searchTags=listOf("bring meat","valley of mines - castle","local quest giver in valley of mines - castle","engor")),
        Quest("CH2-144",2,144,"Gold for Brutus",category="Valley of Mines - Castle",giver = "Brutus",location="Valley of Mines - Castle",prerequisites="Available before Chapter 4.",summary="Find 200 gold for Brutus so he will teach strength in Garond's castle.",walkthroughSteps=listOf("Find Brutus, the castle torturer, and ask about strength training.","He asks for the 200 gold taken by his companion Dan when Dan escaped.","You can pay Brutus 200 gold from your own purse immediately.","Alternatively, search the switchback path toward the Valley of Mines pass for Dan's corpse among dragon snappers and fire lizards.","Loot Dan's 200 gold and return to Brutus to settle the request."),reward="Pay or recover Brutus's 200 gold so that he will offer Strength training; the 200 gold is a cost or recovered debt, not a quest reward.",warnings="You can recover Dan's gold rather than spending 200 of your own.",searchTags=listOf("gold for brutus","valley of mines - castle","local quest giver in valley of mines - castle")),
        Quest("CH2-145",2,145,"Freeing Gorn",category="Valley of Mines - Castle",giver = "Milten",location="Valley of Mines - Castle",prerequisites="Complete before Chapter 3 for the direct rescue route.",summary="Raise Gorn's 1,000-gold ransom, pay Garond and release him from the castle prison.",walkthroughSteps=listOf("Ask Milten in Garond's castle about your old companions and learn that Gorn is imprisoned.","Speak to Garond, who demands 1,000 gold for Gorn's release.","Return to Milten and Diego, who can contribute 250 and 300 gold respectively.","Optionally take another 350 gold from Gorn's stash inside the ruined tower section near the castle's ram.","Pay Garond the full ransom and visit Gorn in the prison.","Free Gorn and meet him and Milten in the mages' quarters to finish the rescue."),reward="Free Gorn by paying Garond's 1,000-gold ransom; Gorn's release advances Milten's and Gorn's storylines.",warnings="The 1,000 gold is a ransom you pay, not money you receive.",searchTags=listOf("freeing gorn","valley of mines - castle","local quest giver in valley of mines - castle")),
        Quest("CH2-146",2,146,"Escape",category="Valley of Mines - Castle",giver="Cliff",location="Valley of Mines - Castle",prerequisites="Free Gorn from the castle prison and wait several days.",summary="Help Cliff escape the castle and reach Netbek's forest camp.",walkthroughSteps=listOf("Speak to Cliff about his plan to escape.","Locate Netbek's forest camp and return to Cliff with a destination.","At night, bring Cliff a weapon and either hunters' armor or minecrawler-plate armor.","Meet Cliff near the castle's ram and escort him to Netbek's camp near the shapeshifters' monastery.","Use the key awarded at the camp on the chest in the former Rice Lord's house; it leads to another chest key in the castle tower."),reward="Escort Cliff to Netbek's camp and obtain a chest key; its chest leads to another key in the castle tower.",warnings="The chest key starts a linked series of caches; don't discard it after escorting Cliff.",searchTags=listOf("escape","valley of mines - castle","local quest giver in valley of mines - castle","cliff")),
        Quest("CH2-147",2,147,"Oric's Pleas",category="Valley of Mines - Castle",giver = "Oric",location="Valley of Mines - Castle",prerequisites="Chapter 2; Speak with paladin Oric inside Garond's castle about the missing shrine to Innos.",summary="Bring paladin Oric a small statuette of Innos to restore his spirits in Garond's castle.",walkthroughSteps=listOf("Speak with paladin Oric inside Garond's castle about the missing shrine to Innos.","Look for a small Innos statuette in your inventory or buy one elsewhere.","If you have none, search the locked chest in the right-hand room on the castle's second floor.","Give Oric the statuette to complete his request."),reward="Deliver a statuette of Innos to Oric to restore his spirits; exact XP reward not verified.",warnings="Complete the related faction and chapter prerequisites before this objective. Source: https://rpgrussia.com/threads/molby-orika.66947/",searchTags=listOf("oric's pleas","valley of mines - castle","local quest giver in valley of mines - castle")),
        Quest("CH2-148",2,148,"Coal Supplies in the Castle",category="Valley of Mines - Castle",giver="Dobar",location="Valley of Mines - Castle",prerequisites="Chapter 2; Talk to smith Dobar about the missing coal.",summary="Recover coal packages for Dobar in Garond's castle.",walkthroughSteps=listOf("Talk to smith Dobar about the missing coal.","Search near the furnaces at the Old Mine by Marcos's mine area, or at the Free Mine above the New Camp.","Bring at least one coal package back to Dobar."),reward="Turn in coal packages to Dobar and improve the forge's supply; exact XP not verified.",warnings="Dobar dies in Chapter 4, so complete this in Chapter 2 or 3.",searchTags=listOf("coal supplies in the castle","valley of mines - castle","local quest giver in valley of mines - castle","dobar")),
        Quest("CH2-149",2,149,"Reconnaissance of the Free Mine",category="Valley of Mines - Castle",giver="Garond",location="Valley of Mines - Castle",prerequisites="Have already investigated the mining camps as part of Garond's ore report.",summary="Investigate the former Free Mine for Garond, recover access, and eliminate the orc commander.",walkthroughSteps=listOf("Talk to Garond about the former New Camp Free Mine and agree to scout it.","Visit the Free Mine entrance and return to report its current condition.","Defeat the orc Agrok near the blocked winch and take his key to open the mine.","Explore inside and defeat the orc commander Var-Ugor near the smelter.","Return to Garond after the commander is dead."),reward="Staged XP rewards, including 200 XP scouting and 3,500 XP plus 1,000 gold at final turn-in, according to the April 2026 guide.",warnings="https://rpgrussia.com/threads/razvedka-svobodnoj-shaxty.66949/",searchTags=listOf("reconnaissance of the free mine","valley of mines - castle","local quest giver in valley of mines - castle")),
        Quest("CH2-150",2,150,"Missing in Action",category="Valley of Mines - Castle",giver="Garond",location="Valley of Mines - Castle",prerequisites="Chapter 2; Ask Garond about the missing groups under Albert and Wenzel.",summary="Find out what happened to Wenzel's and Albert's paladin detachments.",walkthroughSteps=listOf("Ask Garond about the missing groups under Albert and Wenzel.","Find Albert's camp below Netbek's forest camp and report to Garond.","Ask Jergan at Fajeth's camp and Talbin above Cavalorn's hut about Wenzel's group.","Learn that Wenzel was captured by orcs, then speak to Garond about freeing the prisoners.","Earn access to the Orc Mine through Ur-Thrall in Orc City, complete the required mine questline, and free Wenzel.","Return to Garond with news of both groups."),reward="Report the fate of Albert's and Wenzel's paladins to Garond after advancing the Orc Mine questline.",warnings="Garond's missing detachment inquiry ties into the Orc Mine; Wenzel cannot be freed without progressing the slave-escape chain.",searchTags=listOf("missing in action","valley of mines - castle","local quest giver in valley of mines - castle","garond")),
        Quest("CH2-151",2,151,"Food for the Paladins in the Castle",category="Valley of Mines - Castle",giver="Garond",location="Valley of Mines - Castle",prerequisites="Chapter 2; Ask Garond about the food shortage.",summary="Deliver food supplies for the castle's paladins.",walkthroughSteps=listOf("Ask Garond about the food shortage.","Gather 50 pieces of raw meat and 50 fish.","Deliver the supplies to Garond."),reward="Deliver 50 raw meat and 50 fish to Garond to provision the castle; exact XP/gold not verified.",warnings="Do not sell unique named items, special ingredients, quest letters or unusual trophies until the related quest chain is finished.",searchTags=listOf("food for the paladins in the castle","valley of mines - castle","local quest giver in valley of mines - castle","garond")),
        Quest("CH2-152",2,152,"Tactical Advantage",category="Valley of Mines - Castle",giver="Parcival",location="Valley of Mines - Castle",prerequisites="Chapter 2; Accept Parcival's assignment at Garond's castle.",summary="Eliminate the orc crossbowmen, warriors and leader occupying the cliff.",walkthroughSteps=listOf("Accept Parcival's assignment at Garond's castle.","Clear the orc crossbowmen, fighters and leader on the nearby cliff.","Search the cave where the leader and a spider may be hiding, if the quest does not complete.","Return to Parcival for the reward."),reward="Defeat the orc defenders on the cliff and report to Parcival; exact XP not verified.",warnings="If the journal does not update, leave the area and revisit all cliff positions, including the cave.",searchTags=listOf("tactical advantage","valley of mines - castle","local quest giver in valley of mines - castle","parcival")),
        Quest("CH2-153",2,153,"Secrets of the Temple of Adanos",category="Valley of Ashtar / Plateau of the Ancients",giver="Ancient tablet in the Temple of Adanos (automatic)",location="Valley of Ashtar / Plateau of the Ancients",prerequisites="Raven has vanished during the Temple of Adanos confrontation; take and read the ancient tablet from the secret room.",summary="Use Raven's ancient tablet and the Sun Key to reach the Plateau of the Ancients, complete Adanos's trials, and eventually defeat Raven.",walkthroughSteps=listOf("After Raven's disappearance, enter the hidden portal chamber and collect the ancient tablet, stone crystal (Sun Key), and Summon Stone Guardian rune.","Read the tablet, consult Saturas, and place the stone crystal on the pyramid pedestal to activate a teleporter.","Defeat the stone puma, retrieve the focus stone, activate the next teleporter and meet the golden dragon Ash'Tar.","Charge the ancient tablet at the runic altar in the Scholars' Library using the summoning rune.","Return to the Temple of Adanos, summon the ancient guardian, then acquire the guardian-defeating weapon from the Warriors' Temple.","Defeat the guardian, take its runic heart and use the heart on the magic sphere in the Scholars' Library to open the Plateau of the Ancients.","Gather four oasis keys and tablet fragments, explore the Tears shrine, defeat its guardians and the Titan, and assemble the rune tablet.","Pass the trials in the Temple of Truth, restore the Tree of Life, and obtain the Crown of Ice.","Wear the crown and Scepter of Adanos at the altar, cross the bridge to Adanar, and defeat Raven in his Nightmare instance.","Report the final victory to Adanar, Saturas and Ash'Tar."),reward="Unlock the Plateau of the Ancients, complete Adanos's trials, and finish the extended Raven/Adanar storyline; rewards are staged and depend on related routes.",warnings="This extended Adanos chain spans several locations; do not mistake the first Raven encounter for the entire questline.",searchTags=listOf("secrets of the temple of adanos","valley of ashtar / plateau of the ancients","local quest giver in valley of ashtar / plateau of the ancients")),
        Quest("CH2-154",2,154,"Raven's Nightmare",category="Valley of Ashtar / Plateau of the Ancients",giver="Raven",location="Valley of Ashtar / Plateau of the Ancients",prerequisites="Reach the ruined valley behind the Desert of Adanos and meet the challenge requirements; make a separate save.",summary="Enter Raven's nightmare through the conversation with him beyond the Desert of Adanos.",walkthroughSteps=listOf("Complete the Desert of Adanos progression and reach the valley with the temple beyond the main pyramid.","Speak with Raven opposite the temple entrance to enter Raven's Nightmare.","Follow the cliffside and defeat the lizardman boss, activating the wall button and switch.","Cross the bridge after speaking to the spirit, clear the cemetery and progress through the successive boss battles and switches.","Use the nearby Meatbug Transformation scroll to crawl through a gap, defeat the Dark Guardian and the mage boss, and continue through the final chambers.","Complete the entire nightmare before attempting to leave; return to the main story afterward."),reward="Complete the Nightmare instance, including the Dark Guardian and mage boss, to resume Raven's extended story; exact XP not verified.",warnings="This is a difficult, one-way instance until completed. Community guide recommends at least 2000 health and 250 strength/dexterity or 500 mana.",searchTags=listOf("raven's nightmare","valley of ashtar / plateau of the ancients","local quest giver in valley of ashtar / plateau of the ancients")),
        Quest("CH2-155",2,155,"Artifacts of Antiquity",category="Valley of Ashtar / Plateau of the Ancients",giver="Saturas",location="Valley of Ashtar / Plateau of the Ancients",prerequisites="Carry the Sun Key stone crystal found after Raven vanishes, then discuss it with Saturas.",summary="Follow Ash'Tar's explanation of the Claw of Beliar and decide how to deal with the archdemon S'Enyak.",walkthroughSteps=listOf("Collect the Sun Key after Raven vanishes and show it to Saturas.","Advance Secrets of the Temple of Adanos, find the golden dragon Ash'Tar and discuss the Claw of Beliar's imprisoned archdemon.","Defeat Raven in Raven's Nightmare and recover the Claw; show it to Ash'Tar.","Choose whether to destroy the Claw for experience and learning points, or preserve it for the demon-soul route.","If keeping it, either collect four elemental spheres to create Cross of Elements and kill S'Enyak, or learn Mora Ulartu through Xardas/Kreol and obtain the Triramar amulet.","Summon S'Enyak with Ash'Tar's horn and resolve the chosen demon route.","If the soul is captured, consult Xardas or Kreol and strengthen the Claw at a Beliar shrine."),reward="Open the S'Enyak/Claw of Beliar empowerment path through Ash'Tar; final power depends on your choice of demon route.",warnings="Decisions are mutually exclusive. Destroying the Claw prevents Mora Ulartu. Source: https://rpgrussia.com/threads/artefakty-drevnosti.67354/ (updated May 2026).",searchTags=listOf("artifacts of antiquity","valley of ashtar / plateau of the ancients","local quest giver in valley of ashtar / plateau of the ancients")),
